// Run only through scripts/whatif-verify.sh's copied-data lifecycle wrapper.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE);
const out=process.env.SCREENSHOT_DIR||'.superpowers/sdd/2026-09-10-spending-first-optimizer/task-6-browser';fs.mkdirSync(out,{recursive:true});
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH,args:['--no-sandbox']});
 let page;try{
  page=await browser.newPage({viewport:{width:1440,height:1000}});page.setDefaultTimeout(30000);const errors=[],graphs=[];page.on('pageerror',e=>errors.push(e.message));
  page.on('response',async r=>{if(r.url().endsWith('/spending/optimize/graph')&&r.status()===200){try{graphs.push(await r.json())}catch{}}});
  await page.goto('http://localhost:8099/whatif',{waitUntil:'domcontentloaded',timeout:60000});
  await page.locator('#spending-optimizer').waitFor({state:'attached'});
  const scenario=await page.locator('#scenario-select').inputValue();
  await page.locator('#wf-tab-taxes').click();
  await page.reload({waitUntil:'domcontentloaded'});
  assert.equal(await page.locator('#scenario-select').inputValue(),scenario);
  assert.equal(await page.locator('#wf-tab-taxes').getAttribute('aria-selected'),'true');
  const taxes=await page.evaluate(()=>[...document.querySelectorAll('body *')].filter(e=>e.children.length===0&&/Est\. Taxes/.test(e.textContent)).map(e=>e.parentElement.textContent.trim()));
  assert(taxes.some(v=>/\$[\d,]+/.test(v)),'Est. Taxes tile must be populated');
  const costItems=await page.evaluate(()=>[...document.querySelectorAll('#wf-panel-taxes .text-negative, #wf-panel-taxes [class*=text-red-], #wf-panel-taxes [class*=text-rose-]')].map(e=>({text:e.textContent.trim().slice(0,100),color:getComputedStyle(e).color})).filter(e=>e.text));
  assert(costItems.length>0,'Taxes/IRMAA/NIIT should use cost color');
  await page.locator('#spending-optimizer').evaluate(e=>{for(let p=e.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;for(const d of e.querySelectorAll('details'))d.open=true;e.scrollIntoView()});
  const start=await page.locator('#spending-optimizer').getAttribute('data-plan-start');
  const stop=String(Number(start.slice(0,4))+1)+start.slice(4);
  await page.locator('#spending-minimum').fill('100.25');
  await page.locator('#spending-boost-enabled').check();
  await page.locator('#spending-boost-amount').fill('100.25');
  await page.locator('#spending-boost-stop').fill(stop);
  await page.locator('#spending-search-min').fill('1000.25');
  await page.locator('#spending-search-max').fill('1100.25');
  await page.locator('#spending-search-step').fill('100');
  await page.waitForFunction(()=>document.querySelector('[data-spending-range]').textContent.includes('1,100.25'));
  const started=Date.now();await page.locator('#spending-optimizer-run').click();
  await page.locator('[data-spending-outcome]').waitFor({timeout:180000});
  const searchMs=Date.now()-started;
  assert((await page.locator('[data-spending-outcome]').textContent()).includes('Your spending options'),'copied scenario has qualifying candidates');
  const apply=page.locator('[data-spending-frontier="planned"] [data-spending-apply]').first();
  const candidateID=await apply.getAttribute('data-spending-apply');
  await page.locator(`[data-spending-graph="${candidateID}"]`).first().click();
  await page.waitForFunction(()=>!document.querySelector('#spending-graph-preview').hidden && document.querySelector('#spending-graph-main').data);
  await page.locator('#spending-graph-view').selectOption('timeline');
  await page.waitForFunction(()=>document.querySelector('#spending-graph-data').textContent.includes('Observed calendar-month amounts'));
  await page.locator('#spending-graph-data').evaluate(e=>e.closest('details').open=true);
  for(const width of [1440,375])for(const dark of [false,true]){
   await page.setViewportSize({width,height:width===375?850:1000});
   await page.evaluate(dark=>document.documentElement.classList.toggle('dark',dark),dark);
   await page.waitForFunction(()=>{const p=document.querySelector('#spending-graph-main');return p && p.querySelector('svg') && p.querySelector('svg').getBoundingClientRect().width<=p.getBoundingClientRect().width+2});
   await page.locator('#spending-graph-main').evaluate(e=>e.scrollIntoView({block:'start'}));
   const ticks=await page.locator('#spending-graph-main').evaluate(p=>[...p.querySelectorAll('.xaxislayer-above .xtick text')].map(e=>{const r=e.getBoundingClientRect();return {text:e.textContent,left:r.left,right:r.right}}));
   assert(ticks.length>=2 && ticks.length<=10,'bounded real-app year tick count');
   for(let i=1;i<ticks.length;i++)assert(ticks[i-1].right+4<=ticks[i].left,'real-app calendar labels overlap');
   assert(ticks.every(t=>/^\d{4}$/.test(t.text)),'calendar units remain integer years');
   assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),'page overflows');
   await page.screenshot({path:path.join(out,`timeline-${width}-${dark?'dark':'light'}.png`)});
  }
  assert(graphs.length>0);const graph=graphs.at(-1);
  assert.equal(graph.validation_runs,1000);assert.equal(graph.candidate.living_spending_boost.stop_month,stop);
  assert(graph.funding_timeline.months.length>12);assert(graph.funding_timeline.markers.some(m=>m.kind==='living_spending_boost_stop'));
  await page.setViewportSize({width:1440,height:1000});
  await apply.focus();await apply.press('Enter');
  await page.waitForFunction(()=>document.querySelector('#spending-optimizer')?.textContent.includes('Saved spending plan:'));
  assert.equal(await page.locator('#wf-tab-taxes').getAttribute('aria-selected'),'true','tab must survive Apply partial refresh');
  await page.reload({waitUntil:'domcontentloaded'});
  assert.equal(await page.locator('#scenario-select').inputValue(),scenario);assert.equal(await page.locator('#wf-tab-taxes').getAttribute('aria-selected'),'true');
  assert.equal(await page.locator('#spending-minimum').inputValue(),'100.25');assert.equal(await page.locator('#spending-boost-amount').inputValue(),'100.25');assert.equal(await page.locator('#spending-boost-stop').inputValue(),stop);
  await page.locator('#spending-optimizer').evaluate(e=>{for(let p=e.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;for(const d of e.querySelectorAll('details'))d.open=true});
  await page.locator('#spending-minimum').fill('100000000');
  await page.locator('#spending-boost-enabled').uncheck();
  await page.locator('#spending-search-min').fill('100000000');
  await page.locator('#spending-search-max').fill('100000000');
  await page.locator('#spending-search-step').fill('100');
  await page.waitForFunction(()=>document.querySelector('[data-spending-range]').textContent.includes('100,000,000'));
  await page.locator('#spending-optimizer-run').click();
  await page.locator('[data-spending-outcome]').waitFor({timeout:180000});
  assert.equal((await page.locator('[data-spending-outcome]').textContent()).trim(),'No spending option met your minimum');
  assert.equal(await page.locator('[data-spending-apply]').count(),0);
  const infeasibleEvidence=await page.locator('#spending-optimizer-results').textContent();
  assert(infeasibleEvidence.includes('minimum'),'failed evidence is visible');
  await page.locator('[data-spending-outcome]').scrollIntoViewIfNeeded();
  await page.screenshot({path:path.join(out,'infeasible-desktop.png')});
  await page.reload({waitUntil:'domcontentloaded'});
  assert.equal(await page.locator('#spending-minimum').inputValue(),'100.25','failed preview changed saved minimum');
  assert.deepEqual(errors,[]);
  fs.writeFileSync(path.join(out,'evidence.json'),JSON.stringify({scenario,start,stop,searchMs,taxes,costItems,graph,infeasibleEvidence,errors},null,2));
  console.log(JSON.stringify({status:'PASS',searchMs,scenario,start,stop,graphMonths:graph.funding_timeline.months.length,seeds:[graph.search_seed,graph.selection_seed,graph.validation_seed],themes:['light','dark'],widths:[1440,375],pageErrors:errors}));
 }catch(error){if(page){await page.screenshot({path:path.join(out,"failure.png")});fs.writeFileSync(path.join(out,"failure.html"),await page.content());}throw error}finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
